local SaltpeterRefinery = {}
local PRODUCTS = {
    crude_saltpeter = { name = "Surova salitra", earthCost = 3, time = 2, cost = 15, purity = 30, description = "Surova salitra iz gnojnih kupov." },
    refined_saltpeter = { name = "Rafinirana salitra", earthCost = 3, waterCost = 1, time = 4, cost = 40, purity = 50, prestige = 1, description = "Rafinirana salitra z raztopino." },
    crystallized_saltpeter = { name = "Kristalizirana salitra", earthCost = 3, waterCost = 2, time = 6, cost = 100, purity = 70, prestige = 3, happiness = 1, description = "Kristalizirana salitra za fine smodnike." },
    white_saltpeter = { name = "Bela salitra", earthCost = 4, waterCost = 2, charcoalCost = 1, time = 8, cost = 240, purity = 85, prestige = 6, happiness = 2, description = "Bela salitra z ogljeno filtracijo." },
    silver_treated_saltpeter = { name = "Srebrno obdelana salitra", earthCost = 4, waterCost = 2, silverCost = 1, charcoalCost = 1, time = 11, cost = 540, purity = 95, prestige = 12, happiness = 3, description = "Srebrno obdelana salitra za kraljeve smodnike." },
    royal_pure_saltpeter = { name = "Kraljevski čista salitra", earthCost = 6, waterCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, time = 16, cost = 1400, purity = 100, prestige = 36, happiness = 8, description = "Velika kraljevska čista salitra z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Salitrarska delavnica", cost = { gold = 300, wood = 150, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    leaching_vat = { name = "Izluževalna kadi", cost = { gold = 1000, wood = 300, stone = 400, earth = 10 }, upkeep = 24, qualityBonus = 18 },
    crystallization_room = { name = "Kristalizirnica", cost = { gold = 2500, wood = 500, stone = 700, silver = 40, water = 10 }, upkeep = 60, qualityBonus = 30 },
    royal_saltpeter_atelier = { name = "Kraljevski atelje salitre", cost = { gold = 10000, wood = 800, stone = 1500, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 40 },
}
SaltpeterRefinery.earthStock = 18; SaltpeterRefinery.waterStock = 14; SaltpeterRefinery.charcoalStock = 12; SaltpeterRefinery.silverStock = 8; SaltpeterRefinery.goldStock = 6; SaltpeterRefinery.jewelStock = 6
SaltpeterRefinery.productStock = {}; SaltpeterRefinery.buildings = {}; SaltpeterRefinery.maker = nil; SaltpeterRefinery.activeMaking = {}; SaltpeterRefinery.totalProducts = 0; SaltpeterRefinery.dayTimer = 0
function SaltpeterRefinery.init() SaltpeterRefinery.earthStock=18; SaltpeterRefinery.waterStock=14; SaltpeterRefinery.charcoalStock=12; SaltpeterRefinery.silverStock=8; SaltpeterRefinery.goldStock=6; SaltpeterRefinery.jewelStock=6; SaltpeterRefinery.productStock={}; SaltpeterRefinery.buildings={}; SaltpeterRefinery.maker=nil; SaltpeterRefinery.activeMaking={}; SaltpeterRefinery.totalProducts=0; SaltpeterRefinery.dayTimer=0; print("[SaltpeterRefinery] Royal Saltpeter Refinery System initialized (6 products, 4 buildings)") end
function SaltpeterRefinery.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaltpeterRefinery.maker={name=n or ("Salitrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Salitrar najet: %s (spretnost: %d)",SaltpeterRefinery.maker.name,s),"success") end; return true end
function SaltpeterRefinery.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaltpeterRefinery.build(id) local ok,e=SaltpeterRefinery.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaltpeterRefinery.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaltpeterRefinery.getQualityBonus() local b=0; for _,bd in ipairs(SaltpeterRefinery.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaltpeterRefinery.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.earthCost and SaltpeterRefinery.earthStock<(d.earthCost or 0) then return false,"Premalo zemlje" end; if d.waterCost and SaltpeterRefinery.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.charcoalCost and SaltpeterRefinery.charcoalStock<(d.charcoalCost or 0) then return false,"Premalo oglja" end; if d.silverCost and SaltpeterRefinery.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaltpeterRefinery.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaltpeterRefinery.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SaltpeterRefinery.buildings==0 then return false,"Potrebna delavnica" end; if not SaltpeterRefinery.maker then return false,"Potreben salitrar" end; return true end
function SaltpeterRefinery.make(pt,qty) qty=qty or 5; local ok,e=SaltpeterRefinery.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.earthCost then SaltpeterRefinery.earthStock=SaltpeterRefinery.earthStock-d.earthCost*qty end; if d.waterCost then SaltpeterRefinery.waterStock=SaltpeterRefinery.waterStock-d.waterCost*qty end; if d.charcoalCost then SaltpeterRefinery.charcoalStock=SaltpeterRefinery.charcoalStock-d.charcoalCost*qty end; if d.silverCost then SaltpeterRefinery.silverStock=SaltpeterRefinery.silverStock-d.silverCost*qty end; if d.goldCost then SaltpeterRefinery.goldStock=SaltpeterRefinery.goldStock-d.goldCost*qty end; if d.jewelCost then SaltpeterRefinery.jewelStock=SaltpeterRefinery.jewelStock-d.jewelCost*qty end; local t=d.time; if SaltpeterRefinery.maker then t=math.max(1,t-math.floor(SaltpeterRefinery.maker.skill/12)) end; table.insert(SaltpeterRefinery.activeMaking,{id="saltpeter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaltpeterRefinery.completeMaking(m) local q=1.0+(SaltpeterRefinery.getQualityBonus()/100); if SaltpeterRefinery.maker then q=q+(SaltpeterRefinery.maker.skill/180) end; q=math.min(2.0,q); SaltpeterRefinery.productStock[m.productType]=(SaltpeterRefinery.productStock[m.productType] or 0)+m.quantity; SaltpeterRefinery.totalProducts=SaltpeterRefinery.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaltpeterRefinery.maker then SaltpeterRefinery.maker.itemsMade=SaltpeterRefinery.maker.itemsMade+m.quantity; if math.random()<0.20 then SaltpeterRefinery.maker.skill=math.min(100,SaltpeterRefinery.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Salitra izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saltpeter.completed",{productName=m.productName,purity=m.purity}) end end
function SaltpeterRefinery.update(dt) if not _G.state then return end; SaltpeterRefinery.dayTimer=SaltpeterRefinery.dayTimer+dt; if SaltpeterRefinery.dayTimer>=30 then SaltpeterRefinery.dayTimer=0; for i=#SaltpeterRefinery.activeMaking,1,-1 do local m=SaltpeterRefinery.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaltpeterRefinery.completeMaking(m); table.remove(SaltpeterRefinery.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaltpeterRefinery.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaltpeterRefinery.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaltpeterRefinery.getStats() return {earthStock=SaltpeterRefinery.earthStock,waterStock=SaltpeterRefinery.waterStock,charcoalStock=SaltpeterRefinery.charcoalStock,silverStock=SaltpeterRefinery.silverStock,goldStock=SaltpeterRefinery.goldStock,jewelStock=SaltpeterRefinery.jewelStock,productStock=SaltpeterRefinery.productStock,numBuildings=#SaltpeterRefinery.buildings,hasMaker=SaltpeterRefinery.maker~=nil,makerName=SaltpeterRefinery.maker and SaltpeterRefinery.maker.name or "—",makerSkill=SaltpeterRefinery.maker and SaltpeterRefinery.maker.skill or 0,activeMaking=#SaltpeterRefinery.activeMaking,totalProducts=SaltpeterRefinery.totalProducts} end
return SaltpeterRefinery
